-- Explainable catalogue health reports generated by trusted CI.
-- This migration defines the schema only; it does not execute against production.
-- Source of truth remains public/data/software.json in Git.
create table if not exists public.catalog_quality_runs (
  id uuid primary key default gen_random_uuid(),
  source_commit_sha text not null check (source_commit_sha ~ '^[0-9a-f]{40}$'),
  algorithm_version text not null check (algorithm_version ~ '^lsl-catalog-health-v[0-9]+$'),
  entry_count integer not null check (entry_count > 0),
  overall_score smallint not null check (overall_score between 0 and 100),
  recommendation text not null check (recommendation in ('ready', 'review', 'needs_attention')),
  finding_count integer not null check (finding_count >= 0),
  severity_counts jsonb not null default '{"error":0,"warning":0,"info":0}'::jsonb
    check (jsonb_typeof(severity_counts) = 'object'),
  created_at timestamptz not null default now()
);

create table if not exists public.catalog_quality_findings (
  id bigint generated always as identity primary key,
  run_id uuid not null references public.catalog_quality_runs(id) on delete cascade,
  software_id text,
  rule_code text not null check (rule_code ~ '^[a-z][a-z0-9_]{1,63}$'),
  severity text not null check (severity in ('error', 'warning', 'info')),
  deduction smallint not null check (deduction between 0 and 100),
  message text not null check (length(message) between 1 and 500),
  created_at timestamptz not null default now()
);

create index if not exists catalog_quality_runs_created_idx
  on public.catalog_quality_runs (created_at desc);
create index if not exists catalog_quality_findings_run_idx
  on public.catalog_quality_findings (run_id, severity);
create index if not exists catalog_quality_findings_software_idx
  on public.catalog_quality_findings (software_id, created_at desc);

alter table public.catalog_quality_runs enable row level security;
alter table public.catalog_quality_findings enable row level security;

revoke all on table public.catalog_quality_runs from public, anon, authenticated;
revoke all on table public.catalog_quality_findings from public, anon, authenticated;

-- Active admins can read reports; browser clients cannot insert, update, or delete.
grant select on table public.catalog_quality_runs to authenticated;
grant select on table public.catalog_quality_findings to authenticated;

drop policy if exists catalog_quality_runs_admin_read on public.catalog_quality_runs;
create policy catalog_quality_runs_admin_read
  on public.catalog_quality_runs
  for select
  to authenticated
  using (
    exists (
      select 1 from public.lsl_admin_users
      where user_id = (select auth.uid()) and active is true
    )
  );

drop policy if exists catalog_quality_findings_admin_read on public.catalog_quality_findings;
create policy catalog_quality_findings_admin_read
  on public.catalog_quality_findings
  for select
  to authenticated
  using (
    exists (
      select 1 from public.lsl_admin_users
      where user_id = (select auth.uid()) and active is true
    )
  );

-- Trusted server-side CI credentials (never browser credentials) own report writes.
-- No anon/authenticated write grants or permissive write policies are created.
